    location = coalesce(excluded.location, public.events.location);

with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '大工の聖ヨセフ', 'ジョルジュ・ド・ラ・トゥール', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Saint_Joseph_Charpentier.jpg/960px-Saint_Joseph_Charpentier.jpg', '17世紀フランスの画家ラ・トゥールが、1638年から1645年ごろに描いたとされる作品で、ルーヴル美術館が所蔵しています。大工のヨセフが身をかがめて錐で木材に穴をあけ、そのかたわらで幼いイエスがろうそくを掲げています。ほとんど茶色だけの落ち着いた色調の中で、炎の光がイエスの指を透かすように照らすところが見どころです。カラヴァッジョに通じる強い明暗の表現を、静かな祈りの場面に生かしています。', 'CC BY-SA 4.0', 'Georges de La Tour', 'https://commons.wikimedia.org/wiki/File:Saint_Joseph_Charpentier.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('若冲《動植綵絵》全30幅、約10年ぶり一挙公開', '皇居三の丸尚蔵館で2027年2月から、伊藤若冲の国宝《動植綵絵》全30幅を一堂に展示する特別展を開催。', '皇居三の丸尚蔵館（東京都千代田区）で、グランドオープン記念特別展「国宝 動植綵絵 いろどりの世界」が2027年2月4日から3月14日まで開催される。伊藤若冲の《動植綵絵》全30幅を一堂に展示するもので、国内での全30幅の一挙公開は2016年以来約10年ぶりとなる。同館が1993年に開館して以来初めて、また2021年の国宝指定後としても初めての試みだという。展示は「動植綵絵Ⅰ 春から夏へ」「華を競う—近世京都の花鳥画」「動植綵絵Ⅱ 秋から冬へ」の3章で構成され、会期中には一部作品の展示替えがある。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33307',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「オルセー美術館所蔵 いまを生きる歓び」開幕', '東京都美術館でオルセー美術館の約110点を紹介する展覧会が開幕。ミレー《落穂拾い》やゴッホ《星月夜》が上野に。', '東京都美術館で「東京都美術館開館100周年記念 オルセー美術館所蔵 いまを生きる歓び」が開幕した。会期は2026年11月14日から2027年3月28日まで。オルセー美術館の約10万点のコレクションから選ばれた絵画、彫刻、工芸、写真など約110点を紹介し、その約7割が日本初公開となる。23年ぶりの来日となるジャン＝フランソワ・ミレー《落穂拾い》（1857）、フィンセント・ファン・ゴッホ《星月夜》（1888）、16年ぶりの来日となるポール・ゴーガン《アレアレア》（1892）などが並ぶ。構成はプロローグとエピローグを含む全7編で、展示空間のデザインはセノグラファーのセシル・ドゥゴが担当した。', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Jean-Fran%C3%A7ois_Millet_-_Des_glaneuses.jpg/960px-Jean-Fran%C3%A7ois_Millet_-_Des_glaneuses.jpg', '展覧会', 'https://bijutsutecho.com/magazine/news/report/33332',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jean-François_Millet_-_Des_glaneuses.jpg')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「エッシャー 無限のつくりかた」2027年開催', 'M.C.エッシャー財団の所蔵品から代表作を含む約200点を紹介する展覧会が、2027年夏に東京で開幕し全国を巡回。', 'M.C.エッシャー財団が保有するコレクションから、代表作を含む約200点を紹介する展覧会「エッシャー 無限のつくりかた」の開催が発表された。東京展は2027年7月2日から9月26日まで、CREATIVE MUSEUM TOKYO（東京都中央区京橋）で開かれる。その後、大阪・あべのハルカス美術館に2027年10月9日から12月8日まで巡回し、名古屋と静岡での開催は2028年を予定している。初期の風景・建築表現から、平面充填、「無限」や「不可能空間」の表現まで創作の変遷をたどり、独創的な作品世界の形成過程に迫る内容となる。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33310',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('さいたま国際芸術祭2027、第1弾参加作家発表', '2027年10月から開催される「さいたま国際芸術祭2027」の第1弾参加アーティスト8名が決定。テーマは「Awe！」。', '「さいたま国際芸術祭2027」が2027年10月23日から12月26日まで開催される。テーマは「Awe！［オゥ］」。アートプロジェクトのディレクターを湯浅永麻、市民プロジェクトのディレクターを小林優佳が務める。第1弾参加アーティストとして8名が決定し、アートプロジェクトにはイリ・キリアン、梅田哲也、シンディー・望月、向井山朋子の4名が参加する。会場はUrawa U Hall（市民会館うらわ）、うらわ美術館、埼玉会館、埼玉県立近代美術館、大宮盆栽美術館、漫画会館、鉄道博物館、岩槻人形博物館などが予定されている。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33306',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('札幌国際芸術祭2027、全34組と会場構成を発表', '2027年1月開幕の「札幌国際芸術祭2027」の全参加アーティスト34組と、各会場のコンセプトが明らかに。', '「札幌国際芸術祭2027（SIAF2027）」の全参加アーティスト34組と各会場のコンセプトが明らかになった。会期は2027年1月16日から2月21日まで、札幌市内11会場を中心に開催される。テーマは「PLANET SNOW（プラネット・スノー）—upas mintar / upas nociw」で、札幌の街を「雪の惑星」に見立て、各会場には「情報館」「博物館」「地下道」「学校」などの役割が与えられる。ディレクターチームは小川秀明、細川麻沙美、漆崇博、丸田知明の4名。人類の歴史を語る巨大なロボットや、流木や獣の骨から生まれた生き物などの作品が紹介されている。', '', '展覧会', 'https://www.tokyoartbeat.com/articles/-/siaf-2027-news-202611',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('種をまく人', 'The Sower', 'ジャン＝フランソワ・ミレー', 'Jean-François Millet',
        1850,
        (select slug from public.art_movements where slug = 'realism'),
        'ボストン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Jean-Fran%C3%A7ois_Millet_-_The_Sower_-_Google_Art_Project.jpg/960px-Jean-Fran%C3%A7ois_Millet_-_The_Sower_-_Google_Art_Project.jpg', '1849年にバルビゾン村へ移ったミレーが、翌1850年に描いた作品です。ボストン美術館の作品のほかに、ほぼ同じ構図のもう一点が山梨県立美術館にあります。夕暮れの畑を大股で進み、腕を大きく振って種をまく農夫を、画面いっぱいに描いています。この主題の作品は1850年のサロンに出品されて注目と批判を集め、評論家ゴーティエは皮肉を込めて評しました。農家の出身だったミレーは、農民の労働に威厳を与えて描き、神話や歴史ではなく身近な暮らしを主題にする写実主義を進めました。のちにゴッホはこの作品にならって、明るい色で何度も描き直しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jean-François_Millet_-_The_Sower_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('アブサン', 'L''Absinthe', 'エドガー・ドガ', 'Edgar Degas',
        1876,
        (select slug from public.art_movements where slug = 'impressionism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Edgar_Degas_-_In_a_Caf%C3%A9_-_Google_Art_Project_2.jpg/960px-Edgar_Degas_-_In_a_Caf%C3%A9_-_Google_Art_Project_2.jpg', '1875年から1876年にかけて描かれた油彩画で、パリのオルセー美術館が所蔵しています。パリのカフェ「ヌーヴェル・アテーヌ」で、女優エレン・アンドレと画家・版画家のマルスラン・デブータンをモデルに描きました。女性はテーブルのアブサンのグラスをうつろに見つめ、隣の男性は画面の右外に目を向けています。もとの題は「カフェにて」で、1877年の第3回印象派展にも出品されました。1893年にロンドンで展示されたときには、人物の姿が堕落していると非難されました。印象派の仲間が戸外の光を追うなか、ドガは都市の室内と人の孤独に目を向け、斜めから切り取った構図にその特徴がよく表れています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Edgar_Degas_-_In_a_Café_-_Google_Art_Project_2.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ジャック＝ルイ・ダヴィッド', 'Jacques-Louis David', 'ダヴィッド',
        1748, 1825, 'west', array['neoclassicism']::text[],
        'フランス革命とナポレオンの時代を描いた、新古典主義を代表する画家。', '1748年にパリで生まれたフランスの画家です。はじめブーシェを頼りましたが、ブーシェの紹介でジョゼフ＝マリー・ヴィアンに学びました。何度か落選したのち、1774年にローマ賞を受けてイタリアで学んでいます。

1784年の《ホラティウス兄弟の誓い》で、古代を手本にした明快な構図と引き締まった画面を示し、新古典主義の旗手となりました。フランス革命では国民公会の議員となり、王立アカデミーの廃止を進め、《マラーの死》（1793年）を描いています。のちにナポレオンの首席画家となり、《ナポレオン一世の戴冠式》などの大作を手がけました。

王政復古後の1816年にブリュッセルへ亡命し、1825年にその地で亡くなりました。グロ、ジロデ、ジェラール、アングルなど多くの弟子を育て、19世紀のフランス絵画に大きな影響を残しました。', 'https://ja.wikipedia.org/wiki/%E3%82%B8%E3%83%A3%E3%83%83%E3%82%AF%EF%BC%9D%E3%83%AB%E3%82%A4%E3%83%BB%E3%83%80%E3%83%B4%E3%82%A3%E3%83%83%E3%83%89')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('渡辺崋山', 'Watanabe Kazan', '崋山',
        1793, 1841, 'japan', array['nanga']::text[],
        '田原藩の家老を務めながら、写実的な肖像画を描いた江戸後期の画家。', '1793年、江戸の三河田原藩邸に生まれました。絵を金子金陵、ついで谷文晁に学び、儒学を佐藤一斎や松崎慊堂に学んでいます。田原藩では家老として藩政改革を進め、天保の大飢饉では備えの蔵などの対策を行いました。

文人画の素養を持ちながら、肖像画では陰影をつけて人物をきわめて写実的に表しました。西洋画の影響があったと考えられていますが、独自の方法を作り上げたとされます。国宝《鷹見泉石像》（1837年、東京国立博物館）や重要文化財《佐藤一斎像》などが代表作で、町の人々を描いた《一掃百態図》も知られます。

1839年の蛮社の獄で処罰されて田原に蟄居となり、1841年に自ら命を絶ちました。写生にもとづく肖像表現は、江戸後期の絵画に新しい道を開いたものとして評価されています。', 'https://ja.wikipedia.org/wiki/%E6%B8%A1%E8%BE%BA%E5%B4%8B%E5%B1%B1')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('馬遠', 'Ma Yuan', '馬遠',
        null, null, 'east_asia', array['song-yuan']::text[],
        '画面の一角に景色を寄せた構図で知られる、南宋の宮廷画家。', '中国・南宋の画家で、生没年はわかっていません。曾祖父の馬賁から子の馬麟まで、一族は五代にわたって画家を出した家系で、馬遠も光宗・寧宗の時代（おおよそ1189年から1224年）に画院の待詔として宮廷に仕えました。

山水・人物・花鳥のいずれにもすぐれ、「画院中第一」と評されたと伝えられます。同時代の夏珪とともに、景色を画面の一つの角に寄せて広い余白を残す「辺角の景」と呼ばれる構図を用い、李唐・劉松年・夏珪とあわせて南宋四大家に数えられます。

確かな真筆は多くありませんが、日本にも重要文化財《洞山渡水図》（東京国立博物館）や、伝馬遠筆の国宝《風雨山水図》（静嘉堂文庫）などが伝わっています。', 'https://ja.wikipedia.org/wiki/%E9%A6%AC%E9%81%A0')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
